<?php
require __DIR__ . '/_guard.php';
chatweb_admin_require_permission($conn, 'users.view');
$groups = mysqli_query($conn, "SELECT c.id, c.title, c.created_at, u.full_name creator, COUNT(cm.user_id) members FROM conversations c LEFT JOIN users u ON u.id=c.created_by LEFT JOIN conversation_members cm ON cm.conversation_id=c.id WHERE c.type='group' GROUP BY c.id ORDER BY c.id DESC LIMIT 100");
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Group List | Chat Web Admin</title><style>body{margin:0;background:#f7f7f8;font-family:Arial,sans-serif;color:#172033}.main{padding:30px}.panel{background:#fff;border-radius:10px;padding:22px;box-shadow:0 13px 30px rgba(15,23,42,.05);overflow:auto}a{color:#e6a300;text-decoration:none;font-weight:800}table{width:100%;border-collapse:collapse;min-width:760px}th{background:#f0f0f1}th,td{text-align:left;padding:14px;border-bottom:1px solid #e5e7eb}</style></head><body><main class="main"><a href="index.php">Dashboard</a><h1>Group List</h1><section class="panel"><table><thead><tr><th>ID</th><th>Name</th><th>Creator</th><th>Members</th><th>Created</th></tr></thead><tbody><?php while($row=mysqli_fetch_assoc($groups)){ ?><tr><td>#<?php echo (int)$row['id']; ?></td><td><?php echo htmlspecialchars($row['title'] ?: 'Group'); ?></td><td><?php echo htmlspecialchars($row['creator'] ?: '-'); ?></td><td><?php echo (int)$row['members']; ?></td><td><?php echo htmlspecialchars($row['created_at']); ?></td></tr><?php } ?></tbody></table></section></main></body></html>
